files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --button-bg: #1f4287;
  --button-hover: #2a5a9e;
  --button-active: #0a2a4a;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.scoreboard-card {
  background: var(--card-bg);
  border: 4px solid var(--primary);
  border-radius: 12px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 0 var(--primary);
}

.pixel-title {
  text-align: center;
  font-size: 1.8rem;
  margin-bottom: 24px;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 2px;
}

.teams-container {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  justify-content: center;
}

.team {
  flex: 1 1 200px;
  text-align: center;
  background: var(--primary);
  border-radius: 8px;
  padding: 16px;
}

.team-name {
  font-size: 1.2rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.score {
  font-size: 3rem;
  font-weight: bold;
  margin: 8px 0 16px;
  font-variant-numeric: tabular-nums;
}

.button-group {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.score-btn,
.period-btn,
.action-btn {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  background: var(--button-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 48px;
  min-height: 48px;
}

.score-btn:hover,
.period-btn:hover,
.action-btn:hover {
  background: var(--button-hover);
}

.score-btn:active,
.period-btn:active,
.action-btn:active {
  background: var(--button-active);
  transform: translateY(2px);
}

.score-btn:focus-visible,
.period-btn:focus-visible,
.action-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.action-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background: var(--button-bg);
  transform: none;
}

.period-section {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 24px 0;
  font-size: 1.2rem;
}

.period-label {
  font-weight: bold;
}

.period-value {
  font-size: 1.5rem;
  font-weight: bold;
  min-width: 2ch;
  text-align: center;
}

.action-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.action-btn {
  padding: 12px 24px;
  background: var(--accent);
  color: #fff;
  font-weight: bold;
}

.action-btn:hover {
  background: #c73e54;
}

.action-btn:active {
  background: #a83246;
}

[hidden] {
  display: none !important;
}

@media (max-width: 480px) {
  .scoreboard-card {
    padding: 16px;
  }
  .pixel-title {
    font-size: 1.4rem;
  }
  .score {
    font-size: 2.5rem;
  }
  .teams-container {
    gap: 16px;
  }
  .team {
    flex: 1 1 100%;
  }
}

// Pixel Scoreboard logic
const state = {
  team1: 0,
  team2: 0,
  period: 1,
  history: [] // array of { team, delta }
};

const team1ScoreEl = document.getElementById('team1-score');
const team2ScoreEl = document.getElementById('team2-score');
const periodDisplayEl = document.getElementById('period-display');
const undoBtn = document.getElementById('undo-btn');
const resetBtn = document.getElementById('reset-btn');
const periodIncBtn = document.getElementById('period-increment');
const periodDecBtn = document.getElementById('period-decrement');

function updateUI() {
  team1ScoreEl.textContent = state.team1;
  team2ScoreEl.textContent = state.team2;
  periodDisplayEl.textContent = state.period;
  undoBtn.disabled = state.history.length === 0;
  periodIncBtn.disabled = state.period >= 4;
  periodDecBtn.disabled = state.period <= 1;
}

function addScore(team, delta) {
  if (team === 1) state.team1 += delta;
  else if (team === 2) state.team2 += delta;
  state.history.push({ team, delta });
  updateUI();
}

function undo() {
  const last = state.history.pop();
  if (!last) return;
  if (last.team === 1) state.team1 -= last.delta;
  else if (last.team === 2) state.team2 -= last.delta;
  updateUI();
}

function resetGame() {
  state.team1 = 0;
  state.team2 = 0;
  state.period = 1;
  state.history = [];
  updateUI();
}

function changePeriod(delta) {
  const newPeriod = state.period + delta;
  if (newPeriod >= 1 && newPeriod <= 4) {
    state.period = newPeriod;
    updateUI();
  }
}

// Attach event listeners
for (let i = 1; i <= 3; i++) {
  document.getElementById(`team1-add${i}`).addEventListener('click', () => addScore(1, i));
  document.getElementById(`team2-add${i}`).addEventListener('click', () => addScore(2, i));
}

undoBtn.addEventListener('click', undo);
resetBtn.addEventListener('click', resetGame);
periodIncBtn.addEventListener('click', () => changePeriod(1));
periodDecBtn.addEventListener('click', () => changePeriod(-1));

// Initial UI sync
updateUI();
